import requests, numpy as np, pandas as pd, matplotlib.pyplot as plt
AA3={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H',
 'ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V','MSE':'M'}
def fetch(p): return requests.get(f"https://files.rcsb.org/download/{p}.pdb",timeout=120).text
def parse(t,ch=None):
    o=[]
    for ln in t.split("\n"):
        if ln.startswith(("ATOM","HETATM")) and ln[16] in (" ","A"):
            rn=ln[17:20].strip()
            if rn not in AA3: continue
            if ch and ln[21]!=ch: continue
            o.append((ln[12:16].strip(),AA3[rn],int(ln[22:26]),ln[21],
                      np.array([float(ln[30:38]),float(ln[38:46]),float(ln[46:54])])))
    return o
def chains(t): return sorted({ln[21] for ln in t.split("\n") if ln.startswith("ATOM")})
def find_triad(at,cut=3.6):
    ser={n:x for nm,r,n,c,x in at if r=='S' and nm=='OG'}
    his={}; acid={}
    for nm,r,n,c,x in at:
        if r=='H' and nm in ('ND1','NE2'): his.setdefault(n,{})[nm]=x
        if r in 'DE' and nm in ('OD1','OD2','OE1','OE2'): acid.setdefault(n,[]).append(x)
    hits=[]
    for sn,sx in ser.items():
        for hn,hd in his.items():
            for a,b in (('NE2','ND1'),('ND1','NE2')):
                if a in hd and b in hd and np.linalg.norm(sx-hd[a])<cut:
                    for an,axs in acid.items():
                        dd=min(np.linalg.norm(hd[b]-y) for y in axs)
                        if dd<cut: hits.append((sn,hn,an,float(np.linalg.norm(sx-hd[a])),float(dd)))
    return sorted(hits,key=lambda h:h[3])
CHG={'D':-1,'E':-1,'K':1,'R':1}
def pocket(at,sn,r):
    og=[x for nm,_,n,c,x in at if n==sn and nm=='OG'][0]
    res={}
    for nm,aa,n,c,x in at:
        if np.linalg.norm(x-og)<r: res[n]=aa
    return sum(CHG.get(v,0) for v in res.values()), len(res)

PANEL=[("4O8V","A","AlgJ (P. putida)","unknown","acceptor unknown"),
       ("4KNC","A","AlgX (P. aeruginosa)","alginate","polymer acceptor"),
       ("7ULA","A","AlgX in AlgKX (P. putida)","alginate","polymer acceptor"),
       ("7TJB","A","PatB (N. gonorrhoeae)","peptidoglycan","polymer acceptor"),
       ("8TLB","A","PatB (C. jejuni)","peptidoglycan","polymer acceptor"),
       ("5UFY","A","OatA-C (S. pneumoniae)","peptidoglycan","polymer acceptor"),
       ("6VJP",None,"OatA-C (S. aureus)","peptidoglycan","polymer acceptor"),
       ("1IVN",None,"TAP/TesA (E. coli)","water","hydrolase, acceptor water"),
       ("1DEO",None,"RG acetylesterase (A. aculeatus)","water","hydrolase on an anionic polymer")]
rows=[]
for pid,ch,lab,acc,cls in PANEL:
    t=fetch(pid)
    cand=[ch] if ch else chains(t)[:4]
    best=None
    for c in cand:
        at=parse(t,c); h=find_triad(at)
        if h: best=(c,at,h[0]); break
    if not best:
        print("no triad:",pid,lab); continue
    c,at,(sn,hn,an,d1,d2)=best
    row=dict(pdb=pid,chain=c,protein=lab,acceptor=acc,klass=cls,
             triad=f"S{sn}-H{hn}-D/E{an}",SerOG_HisN=round(d1,2),HisN_acid=round(d2,2))
    for r in (10,12,15): row[f"q{r}"],row[f"n{r}"]=pocket(at,sn,r)
    rows.append(row)
df=pd.DataFrame(rows)
pd.set_option("display.width",250); pd.set_option("display.max_columns",30)
print(df.to_string(index=False))
df.to_csv("/tmp/sgnh_panel_full.csv",index=False)

